import { vec2, vec3, float, time, positionWorld, normalWorld, cameraPosition, mix, smoothstep, pow, sqrt, atan2, floor, fract, length, dot, step, hash } from "builtin/tsl";
import { MeshBasicNodeMaterial } from "builtin/three";

const TAU = 6.283185307179586;

function rotateX(v, angle) {
  const c = angle.cos();
  const s = angle.sin();
  return vec3(v.x, v.y.mul(c).sub(v.z.mul(s)), v.y.mul(s).add(v.z.mul(c)));
}
function rotateY(v, angle) {
  const c = angle.cos();
  const s = angle.sin();
  return vec3(v.x.mul(c).sub(v.z.mul(s)), v.y, v.x.mul(s).add(v.z.mul(c)));
}
function rotateZ(v, angle) {
  const c = angle.cos();
  const s = angle.sin();
  return vec3(v.x.mul(c).sub(v.y.mul(s)), v.x.mul(s).add(v.y.mul(c)), v.z);
}
function rotate2D(v, angle) {
  const c = angle.cos();
  const s = angle.sin();
  return vec2(v.x.mul(c).sub(v.y.mul(s)), v.x.mul(s).add(v.y.mul(c)));
}

export function material(ctx) {
  const m = new MeshBasicNodeMaterial();

  // The sky, the nebula, the rim mask: string params re-point them; the literals are the preset's own.
  const sky = ctx.texture(ctx.constants.sky ?? "${D8.sky}");
  const clouds = ctx.texture(ctx.constants.clouds ?? "${D8.clouds}");
  const mask = ctx.texture(ctx.constants.mask ?? "${D8.mask}");

  const viewDir = cameraPosition.sub(positionWorld).normalize();
  const normal = normalWorld.normalize();
  const NdotV = viewDir.dot(normal).clamp(0, 1);

  // A. The sky through the window: the camera-projected lookup, bulged along the normal toward the silhouette, turned.
  const yaw = time.mul(ctx.param("skySpin", 0.023)).add(ctx.param("skyYaw", 3.12));
  const bulge = NdotV.oneMinus().mul(ctx.param("windowBulge", 0.17));
  let lookup = positionWorld.sub(cameraPosition).normalize().add(normal.mul(bulge)).normalize();
  lookup = rotateX(lookup, ctx.param("skyPitch", -0.61));
  lookup = rotateY(lookup, yaw);
  lookup = rotateZ(lookup, ctx.param("skyRoll", 0.26));
  const dirY = lookup.y.clamp(-1, 1);
  const asinY = atan2(dirY, sqrt(float(1).sub(dirY.mul(dirY)).max(1e-5)));
  const skyUv = vec2(atan2(lookup.x, lookup.z).div(TAU).add(0.5), float(0.5).sub(asinY.div(Math.PI)));
  const galaxy = sky.sample(skyUv).rgb.mul(ctx.param("skyBrightness", 1.0));

  // B. The nebula: triplanar clouds in world space, pushed by the view for depth, with a finer layer riding over.
  const cloudTime = time.mul(ctx.param("cloudSpeed", 0.05));
  const cloudWorld = positionWorld.mul(ctx.param("cloudScale", 1.4)).add(viewDir.mul(ctx.param("cloudDepth", 0.4)));
  const blendRaw = normal.abs();
  const triBlend = blendRaw.div(blendRaw.x.add(blendRaw.y).add(blendRaw.z).add(0.001));
  const cloudXY = clouds.sample(cloudWorld.xy.add(vec2(cloudTime.mul(0.7), cloudTime.mul(0.3)))).r;
  const cloudXZ = clouds.sample(cloudWorld.xz.add(vec2(cloudTime.mul(0.5), cloudTime.mul(0.8)))).r;
  const cloudYZ = clouds.sample(cloudWorld.yz.add(vec2(cloudTime.mul(0.4), cloudTime.mul(0.6)))).r;
  const detail = clouds.sample(cloudWorld.xy.mul(1.7).add(vec2(cloudTime.mul(1.1), cloudTime.mul(-0.4)))).r;
  const cloudBase = cloudXY.mul(triBlend.z).add(cloudXZ.mul(triBlend.y)).add(cloudYZ.mul(triBlend.x));
  const cloud = mix(cloudBase, cloudBase.mul(detail).mul(1.5), 0.4);
  const cloudDensity = ctx.param("cloudDensity", 3);
  const nebula = vec3(0.4, 0.133, 0.8).mul(cloud).mul(cloudDensity).add(vec3(0.8, 0.6, 1.0).mul(pow(cloud, 2.5)).mul(cloudDensity).mul(0.4));

  // D. The rim: an edge fresnel under two rotating world-space masks, never darker than rimFloor.
  const fresnel = smoothstep(0.0, float(1).div(ctx.param("rimPower", 0.5)), NdotV.oneMinus());
  const rimWorld = positionWorld.mul(ctx.param("rimMaskScale", 1.0)).add(viewDir.mul(ctx.param("rimMaskDepth", 0.3)));
  const rimTurn = time.mul(ctx.param("rimMaskSpin", 0.055));
  const rimSpeed = ctx.param("rimMaskSpeed", 0.1);
  const rimUv1 = rotate2D(rimWorld.xz, rimTurn).add(vec2(0, time.mul(rimSpeed)));
  const rimUv2 = rotate2D(rimWorld.xy, rimTurn.mul(0.5)).add(vec2(time.mul(rimSpeed).mul(0.7), 0));
  const rimMask = mix(mask.sample(rimUv1).r, mask.sample(rimUv2).r, normal.y.abs());
  const rimGlow = vec3(0.541, 0.816, 1.0).mul(fresnel).mul(mix(ctx.param("rimFloor", 0.32), 1, rimMask)).mul(ctx.param("rimGlow", 11.0));

  // E. The inner glow (inverse fresnel), off at its default.
  const innerGlow = vec3(1.0, 0.4, 0.667).mul(pow(NdotV, ctx.param("innerPower", 2.0))).mul(mix(float(1), cloud, 0.5)).mul(ctx.param("innerGlow", 0.0));

  // F. The stars: one round sparkle per lit cell of the view direction, the field drifting with time.
  const starField = viewDir.mul(50).add(time.mul(ctx.param("starDrift", 1.0)));
  const starCell = floor(starField);
  const lit = step(float(1).sub(ctx.param("starDensity", 0.25).mul(0.1)), hash(dot(starCell, vec3(1.0, 57.0, 113.0))));
  const stars = smoothstep(0.5, 0.12, length(fract(starField).sub(0.5))).mul(lit).mul(ctx.param("starBrightness", 2.0));

  m.colorNode = galaxy.add(nebula).add(rimGlow).add(innerGlow).add(vec3(stars));
  return m;
}
