import { color, positionWorld, normalWorld, cameraPosition, fract, abs, min, smoothstep, mix } from "builtin/tsl";
import { MeshBasicNodeMaterial, DoubleSide } from "builtin/three";

export function material(ctx) {
  const m = new MeshBasicNodeMaterial();
  m.side = DoubleSide;
  // The box stands on the ground, so its floor lies in the ground's own plane: the offset toward the eye lets the plan win the depth test there instead of flickering.
  m.polygonOffset = true;
  m.polygonOffsetFactor = -1;
  m.polygonOffsetUnits = -1;
  const pitch = ctx.param("line", 1);
  const weight = ctx.param("weight", 0.02);
  // A world-space grid on every face: the distance to the nearest metre line along each axis, the two axes the face
  // does not point along (the normal's own axis is flat across the face) - the line is where any of them is under weight.
  const p = positionWorld.div(pitch);
  const d = abs(fract(p).sub(0.5)).negate().add(0.5).mul(pitch); // distance to the nearest grid plane, per axis, in metres (0.5 - |fract - 0.5|)
  const n = abs(normalWorld.normalize());
  // An axis the face POINTS along contributes no line (its planes lie in the face and would smear); a face that only leans toward it keeps them, so a round shape wears the whole grid.
  const along = (c) => smoothstep(0.7, 0.85, c).mul(pitch);
  const dx = d.x.add(along(n.x));
  const dy = d.y.add(along(n.y));
  const dz = d.z.add(along(n.z));
  const nearest = min(min(dx, dy), dz);
  const line = smoothstep(weight.mul(0.5), weight.mul(1.5), nearest).oneMinus();
  const blue = color(ctx.constants.blue ?? "oklch(0.45 0.16 258)");
  const ink = color(ctx.constants.ink ?? "oklch(0.95 0.02 240)");
  // A pale rim where the surface turns away - the silhouette reads on a dark night too.
  const viewDir = cameraPosition.sub(positionWorld).normalize();
  const rim = viewDir.dot(normalWorld.normalize()).abs().clamp(0, 1).oneMinus().pow(3).mul(0.35);
  m.colorNode = mix(mix(blue, ink, line), ink, rim);
  // The plan reads through: the box blends over what stands behind it, and a blended lane never writes depth, so it hides nothing.
  const alpha = typeof ctx.constants.alpha === "number" ? ctx.constants.alpha : 0.35;
  m.opacity = alpha;
  m.transparent = alpha < 1;
  m.fog = false;
  return m;
}
