// places/main/config.yaml scatters it low on the grass between the blades, sized by the item's
// \`scale\` and turned by \`randomRotation\`; with \`useTerrainColor\` on the item it wears the ground's
// own colour, so a blue-grey meadow grows blue-grey clover. Feet at y = 0, +Y up: one short stem
// quad and three leaflets, each a diamond quad facing the sky. Every number here is yours to move.
export function geometry(ctx) {
  const { leaf = 'oklch(0.55 0.13 145)' } = ctx.params;
  ctx.color(leaf);
  const h = 0.07;
  const w = 0.006;
  ctx.quad(-w, 0, 0, w, 0, 0, w * 0.6, h, 0, -w * 0.6, h, 0);
  for (let i = 0; i < 3; i++) {
    const t = (i / 3) * Math.PI * 2 + 0.3;
    const rx = Math.cos(t);
    const rz = Math.sin(t);
    const P = (radius, side, y) => [rx * radius - rz * side, y, rz * radius + rx * side];
    const near = P(0.008, 0, h);
    const left = P(0.019, 0.014, h + 0.006);
    const far = P(0.03, 0, h + 0.01);
    const right = P(0.019, -0.014, h + 0.006);
    ctx.quad(near[0], near[1], near[2], left[0], left[1], left[2], far[0], far[1], far[2], right[0], right[1], right[2]);
  }
}
`,flower:`// A flower on a stem: a plant file (heightmap-terrain skill, decorations). The \`flower\` layer in
// places/main/config.yaml scatters it on the grass beside the blades, sizes each one by the item's
// \`scale\`, turns it by \`randomRotation\`, bends it in the wind by the item's \`wind\`, and colours it by
// the item's \`params\` (petal, heart, stem). Feet at y = 0, +Y up: two crossed stem quads, five petal
// quads cupped in a ring at the top and a heart quad over them. Every number here is yours to move;
// delete the layer and the flowers are gone.
export function geometry(ctx) {
  const { petal = '#ffffff', heart = '#f2c14e', stem = 'oklch(0.52 0.12 140)' } = ctx.params;
  const h = 0.42;
  const w = 0.012;
  ctx.color(stem);
  for (let p = 0; p < 2; p++) {
    const v = (x, y, z) => (p === 0 ? [x, y, z] : [z, y, -x]);
    const a = v(-w, 0, 0);
    const b = v(w, 0, 0);
    const c = v(w * 0.6, h, 0);
    const d = v(-w * 0.6, h, 0);
    ctx.quad(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2], d[0], d[1], d[2]);
  }
  // The head rides the stem's tip whole, so a gust never tears petals off the stalk.
  ctx.sway(1);
  ctx.color(petal);
  const r = 0.06;
  const inner = 0.012;
  for (let i = 0; i < 5; i++) {
    const t0 = (i / 5) * Math.PI * 2;
    const t1 = ((i + 1) / 5) * Math.PI * 2;
    ctx.quad(
      Math.cos(t0) * inner, h, Math.sin(t0) * inner,
      Math.cos(t1) * inner, h, Math.sin(t1) * inner,
      Math.cos(t1) * r, h + 0.015, Math.sin(t1) * r,
      Math.cos(t0) * r, h + 0.015, Math.sin(t0) * r,
    );
  }
  ctx.color(heart);
  ctx.quad(-inner, h + 0.004, -inner, -inner, h + 0.004, inner, inner, h + 0.004, inner, inner, h + 0.004, -inner);
}
`,leaf:`// A fallen leaf: a plant file (heightmap-terrain skill, decorations). The \`leaf\` layer in
// places/main/config.yaml scatters it flat on the grass, sized by the item's \`scale\` and turned by
// \`randomRotation\`; the item's \`params\` colour it (leaf). Feet at y = 0, +Y up: a pointed oval of two
// quads lying a finger above the ground, its middle lifted so the light catches a curl. Several items
// in one layer, each its own colour, make a mixed litter. Every number here is yours to move.
export function geometry(ctx) {
  const { leaf = '#c9782a' } = ctx.params;
  ctx.color(leaf);
  const tip = [-0.06, 0.01, 0];
  const nearLeft = [-0.025, 0.018, -0.03];
  const farLeft = [0.025, 0.022, -0.028];
  const stalk = [0.06, 0.014, 0];
  const farRight = [0.025, 0.022, 0.028];
  const nearRight = [-0.025, 0.018, 0.03];
  ctx.quad(nearLeft[0], nearLeft[1], nearLeft[2], tip[0], tip[1], tip[2], stalk[0], stalk[1], stalk[2], farLeft[0], farLeft[1], farLeft[2]);
  ctx.quad(tip[0], tip[1], tip[2], nearRight[0], nearRight[1], nearRight[2], farRight[0], farRight[1], farRight[2], stalk[0], stalk[1], stalk[2]);
}
`,mushroom:`// A mushroom: a plant file (heightmap-terrain skill, decorations). The \`mushroom\` layer in
// places/main/config.yaml scatters it thinly on the grass, sized by the item's \`scale\` and turned by
// \`randomRotation\`; the item's \`params\` colour it (cap, stem). Feet at y = 0, +Y up: a four-sided
// stem and an eight-sided cap that closes underneath, so it reads from the ground and from above.
// Every number here is yours to move.
export function geometry(ctx) {
  const { cap = '#c0452b', stem = '#f1e7d2' } = ctx.params;
  const stemH = 0.07;
  const stemR = 0.012;
  ctx.color(stem);
  for (let i = 0; i < 4; i++) {
    const t0 = (i / 4) * Math.PI * 2;
    const t1 = ((i + 1) / 4) * Math.PI * 2;
    ctx.quad(Math.cos(t0) * stemR, 0, Math.sin(t0) * stemR, Math.cos(t0) * stemR, stemH, Math.sin(t0) * stemR, Math.cos(t1) * stemR, stemH, Math.sin(t1) * stemR, Math.cos(t1) * stemR, 0, Math.sin(t1) * stemR);
  }
  ctx.color(cap);
  const capR = 0.05;
  const brim = stemH - 0.005;
  const apex = stemH + 0.04;
  for (let i = 0; i < 8; i++) {
    const t0 = (i / 8) * Math.PI * 2;
    const t1 = ((i + 1) / 8) * Math.PI * 2;
    const a = [Math.cos(t0) * capR, brim, Math.sin(t0) * capR];
    const b = [Math.cos(t1) * capR, brim, Math.sin(t1) * capR];
    ctx.tri(a[0], a[1], a[2], 0, apex, 0, b[0], b[1], b[2]);
    ctx.tri(a[0], a[1], a[2], b[0], b[1], b[2], 0, stemH, 0);
  }
}
`,pebble:`// A pebble: a plant file that grows no plant (heightmap-terrain skill, decorations). The \`pebble\`
// layer in places/main/config.yaml scatters it thinly on the grass, sized by the item's \`scale\` and
// turned by \`randomRotation\`; the item's \`params\` colour it (stone). Feet at y = 0, +Y up: a low
// six-sided stone: a ground ring, a shoulder ring and a crown, each ring nudged by ctx.random so no
// two items are the same shape. A decoration has no collider: a rock a player must climb is a
// scatter bed. Every number here is yours to move.
export function geometry(ctx) {
  const { stone = 'oklch(0.6 0.02 80)' } = ctx.params;
  ctx.color(stone);
  const sides = 6;
  const foot = [];
  const shoulder = [];
  for (let i = 0; i < sides; i++) {
    const t = (i / sides) * Math.PI * 2;
    const r0 = 0.09 * (0.85 + ctx.random() * 0.3);
    const r1 = r0 * (0.55 + ctx.random() * 0.25);
    foot.push([Math.cos(t) * r0, 0, Math.sin(t) * r0]);
    shoulder.push([Math.cos(t) * r1, 0.05, Math.sin(t) * r1]);
  }
  const crown = [(ctx.random() - 0.5) * 0.03, 0.08, (ctx.random() - 0.5) * 0.03];
  for (let i = 0; i < sides; i++) {
    const j = (i + 1) % sides;
    const a = foot[i];
    const b = foot[j];
    const c = shoulder[j];
    const d = shoulder[i];
    ctx.quad(a[0], a[1], a[2], d[0], d[1], d[2], c[0], c[1], c[2], b[0], b[1], b[2]);
    ctx.tri(d[0], d[1], d[2], crown[0], crown[1], crown[2], c[0], c[1], c[2]);
  }
}
`,reed:`// A reed: a plant file (heightmap-terrain skill, decorations). The \`reed\` layer in
// places/main/config.yaml scatters it among the blades, sized by the item's \`scale\`, turned by
// \`randomRotation\` and bent in the wind by the item's \`wind\`; the item's \`params\` colour it (stem,
// head). Feet at y = 0, +Y up: two crossed stem quads a metre tall and a slim four-sided seed head
// riding the tip whole. Every number here is yours to move.
export function geometry(ctx) {
  const { stem = 'oklch(0.62 0.1 110)', head = 'oklch(0.45 0.06 60)' } = ctx.params;
  const h = 1.0;
  const w = 0.01;
  ctx.color(stem);
  for (let p = 0; p < 2; p++) {
    const v = (x, y, z) => (p === 0 ? [x, y, z] : [z, y, -x]);
    const a = v(-w, 0, 0);
    const b = v(w, 0, 0);
    const c = v(w * 0.5, h, 0);
    const d = v(-w * 0.5, h, 0);
    ctx.quad(a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2], d[0], d[1], d[2]);
  }
  ctx.sway(1);
  ctx.color(head);
  const r = 0.014;
  const top = h + 0.14;
  for (let i = 0; i < 4; i++) {
    const t0 = (i / 4) * Math.PI * 2;
    const t1 = ((i + 1) / 4) * Math.PI * 2;
    ctx.tri(Math.cos(t0) * r, h, Math.sin(t0) * r, 0, top, 0, Math.cos(t1) * r, h, Math.sin(t1) * r);
  }
}
`},K71=`// The meadow's look on a ground that is not grass (snow, salt, sand, ash): the layer material every
// blade of scripts/grass.js is drawn with (spawn api builtin/three for the material contract;
// heightmap-terrain for the layer). The engine keeps placement, wind and culling; this script owns the
// surface. The blades wear the plant's own colour, the layer material's \`params\` blade, so the field
// keeps its colour on a white or sandy ground. ctx.scatter carries the per-blade facts: groundTint (the
// ground's own colour under the blade's feet: its texture, tint and slow macro drift, as the terrain
// shows it), position (the feet in world metres, one value per blade), heightFraction (0 at the feet,
// 1 at the tip), far (0 at the written density, 1 where distance has thinned the field away). The roots
// lean toward the ground's colour, and where distance thins the field the blades fade into the ground, so
// a still frame reads one place, ground and blades. Blades within one 1.5 m cell share a clump seed
// that leans the colour warm or cool and a little brighter or darker; the roots sit in their own shade
// and the tips in the light; the tips are glossier than the roots so the sun's highlight rides them; a
// blade standing between the eye and the sun lets light through its tip (builtin/lighting's
// sunDirection points toward the sun, and sunRadiance is zero at night, so the glow dies with the sun).
// Every number here is yours to move.
import { color, mix, hash, vec2, vec3, cameraPosition, positionWorld } from 'builtin/tsl';
import { sunDirection, sunRadiance } from 'builtin/lighting';
import { MeshStandardNodeMaterial } from 'builtin/three';

export function material(ctx) {
  const { blade = 'oklch(0.62 0.14 140)' } = ctx.params;
  const m = new MeshStandardNodeMaterial();
  const ground = ctx.scatter.groundTint;
  const feet = ctx.scatter.position;
  const h = ctx.scatter.heightFraction;
  const cell = vec2(feet.x, feet.z).div(1.5).floor();
  const clumpHue = hash(cell.x.mul(157).add(cell.y.mul(311)));
  const clumpValue = hash(cell.x.mul(97).add(cell.y.mul(53)).add(7));
  const clump = color(blade).mul(mix(vec3(1.1, 1.0, 0.85), vec3(0.9, 1.0, 1.12), clumpHue)).mul(mix(0.82, 1.18, clumpValue));
  const root = mix(clump.mul(0.5), ground, 0.35);
  const tip = clump.mul(1.35);
  m.colorNode = mix(mix(root, tip, h.pow(1.3)), ground, ctx.scatter.far);
  m.roughnessNode = mix(0.95, 0.4, h.pow(2));
  const toEye = cameraPosition.sub(positionWorld).normalize();
  const through = toEye.negate().dot(sunDirection).saturate().pow(3);
  m.emissiveNode = tip.mul(sunRadiance).mul(through).mul(h.pow(2)).mul(0.25);
  return m;
}
