`,"scripts/tex-soil.js":`// The top of the ground, drawn in code: one strip, 512 px = 16 m at 32 px a metre, every colour from lib/data/meadow.yml.
// A scene row wears it along the ground line with sprite.repeatX and parallax [1, 1], over the top row of the ground's
// tiles (scripts/tileset-ground.js), so the ground reads as three layers:
//   the turf's lip: bright grass a few px thick, small tufts over it, a ragged fringe of blades hanging under it;
//   the shallow dirt: a lighter soil with sparse specks, root hairs under the turf and a few pebbles;
//   the deep dirt: the tiles themselves, showing under the strip's jagged lower edge.
// The strip is a picture, not a collider: the tiles are the ground. It lies on the ground line (the row's y), not on tiles above or below it.
// M.grass is the turf (root to tip), M.soil the shallow dirt (dark, body, lit).
// A starting picture, yours to redraw or to write over whole.
import M from './lib/data/meadow.yml';
import { rgbs } from './lib/color.js';

var W = 512, H = 56; // the strip in px
var LINE = 8; // the ground line's row: the rows over it hold the tufts
var LIP = 4; // the turf's thickness under the ground line, before the fringe
var FRINGE = [2, 7]; // how far a blade of the fringe hangs under the lip, px
var DEPTH = 36; // the shallow dirt's depth under the ground line, px; the lower edge wanders JAG px round it
var JAG = 6;
var SPECKS = 170, ROOTS = 70, PEBBLES = 7, TUFTS = 230; // how many in the strip

function toward(c, to, t) { return [c[0] + (to[0] - c[0]) * t, c[1] + (to[1] - c[1]) * t, c[2] + (to[2] - c[2]) * t]; }
function hash(n) { n = Math.imul(n ^ (n >>> 15), 0x2c1b3c6d); n = Math.imul(n ^ (n >>> 12), 0x297a2d39); return ((n ^ (n >>> 15)) >>> 0) / 4294967296; }
