  c.fillStyle = palette.leafDark;
  disc(c, 32, 40, 28);
  disc(c, 15, 48, 13);
  disc(c, 49, 48, 13);
  c.fillStyle = palette.leaf;
  disc(c, 32, 34, 26);
  disc(c, 16, 44, 11);
  disc(c, 48, 44, 11);
  disc(c, 32, 18, 14);
  c.fillStyle = palette.leafLit;
  disc(c, 24, 26, 12);
  disc(c, 40, 20, 7);
  disc(c, 14, 40, 5);
