import { MeshToonNodeMaterial } from 'builtin/three';

export function material(ctx) {
  const m = new MeshToonNodeMaterial();
  const root = ctx.scatter.groundTint.mul(0.75);
  const tip = color('oklch(0.86 0.15 128)');
  m.colorNode = mix(root, tip, ctx.scatter.heightFraction.pow(2));
  return m;
}
