// A vertical push reads weaker the steeper the ground (only the cos-of-slope
// component moves the surface outward), so boost by the slope under the cursor
// \u2014 capped so cliffs don't spike.
export function paint(ctx, p, inset, current) {
  const lift = 1 / Math.max(0.4, 1 - ctx.slope(ctx.center));
  return current + ctx.falloff(inset) * ctx.strength * lift;
}
`,"scripts/brushes/lower.js":`
// Same slope boost as Raise \u2014 digging into a steep face needs a deeper vertical
// cut to read as the same change you'd see on flat ground.
export function paint(ctx, p, inset, current) {
  const lift = 1 / Math.max(0.4, 1 - ctx.slope(ctx.center));
  return current - ctx.falloff(inset) * ctx.strength * lift;
}
`,"scripts/brushes/smooth.js":`
// Relax each cell toward the average of its neighbours \u2014 softens spikes/ridges
// without changing overall elevation; runs in GROUND space (GROUND_SPACE_PAINT_SCRIPTS).
// Strength by MAGNITUDE: a negative strength (erase) would relax AWAY from the neighbours
// and run past the local extrema a little more every dab \u2014 only toward settles.
export function paint(ctx, p, inset, current) {
  const d = 0.75;
  const avg = (ctx.readField(ctx.field, p.x + d, p.z) + ctx.readField(ctx.field, p.x - d, p.z) + ctx.readField(ctx.field, p.x, p.z + d) + ctx.readField(ctx.field, p.x, p.z - d)) * 0.25;
  return current + (avg - current) * ctx.falloff(inset) * Math.abs(ctx.strength);
}
`,"scripts/brushes/flatten.js":`
// Level the footprint toward the plane locked at STROKE START \u2014 the height under
// the first dab (ctx.strokeStartValue). Re-sampling under the cursor every dab
// would chase the cursor across a slope and smear terraces instead of holding
// one plane; runs in GROUND space (GROUND_SPACE_PAINT_SCRIPTS): the plane is ground height.
// Strength by MAGNITUDE: a negative strength (erase) would push AWAY from the plane and the
// distance would grow every dab up to the field's clamp \u2014 only toward settles.
export function paint(ctx, p, inset, current) {
  return current + (ctx.strokeStartValue - current) * ctx.falloff(inset) * Math.abs(ctx.strength);
}
`,"scripts/brushes/material.js":`
export function paint(ctx, p, inset, current) {
  const amount = ctx.falloff(inset) * Math.abs(ctx.strength);
  if (ctx.strength >= 0) return Math.max(current, amount);
  return Math.max(0, current - amount);
}
`,"scripts/brushes/scatter-density.js":`
export function paint(ctx, p, inset, current) {
  const amount = ctx.falloff(inset) * Math.abs(ctx.strength);
  if (ctx.strength >= 0) return Math.max(current, amount);
  return Math.max(0, current - amount);
}
`,"scripts/brushes/scatter-spray.js":`
export function paint(ctx, p, inset, current) {
  ctx.ensureScatter({});
  const amount = ctx.falloff(inset) * Math.abs(ctx.strength);
  if (ctx.strength >= 0) return Math.max(current, amount);
  return Math.max(0, current - amount);
}
`,"scripts/brushes/foliage.js":`
export function paint(ctx, p, inset, current) {
  const amount = ctx.falloff(inset) * Math.abs(ctx.strength);
  if (ctx.strength >= 0) return Math.max(current, amount);
  return Math.max(-1, current - amount);
}
`,"scripts/brushes/daisies.js":`
export function paint(ctx, p, inset, current) {
  ctx.ensureScatter({
    density: 5,
    threshold: 0.04,
    sampling: { strategy: "poisson", minDistance: 0.42 },
    variation: { scale: [0.75, 1.25], yaw: [0, 360] },
    templates: [{ weight: 1, sprite: { texture: "cdn/sprite-meadow-daisies-white-yellow-cluster.png", size: [0.65, 0.5], billboard: "yaw", cutout: true }, physics: { body: "none" } }],
  });
  const amount = ctx.falloff(inset) * Math.abs(ctx.strength);
  if (ctx.strength >= 0) return Math.max(current, amount);
  return Math.max(0, current - amount);
}
