  const BREAKS = {
    peony: { v: () => sphereDir().mul(range(3.4, 5.6).mul(sv)), take: 1, life: [1.6, 2.4], fall: 0.3, slow: 1.1, size: [0.05, 0.09], stretch: 0.06, dim: 0.3 },
    ring: { v: () => sphereDir().mul(vec3(1, 0.14, 1)).mul(range(4.8, 5.6).mul(sv)), take: 1, life: [1.5, 2.2], fall: 0.26, slow: 1.15, size: [0.05, 0.08], stretch: 0.06, dim: 0.25 },
    palm: { v: () => cone(38).mul(range(3.6, 5.2).mul(sv)), take: 0.45, life: [1.7, 2.5], fall: 0.5, slow: 0.9, size: [0.09, 0.14], stretch: 0.16, dim: 0.35 },
    willow: { v: () => sphereDir().mul(range(2.3, 3.7).mul(sv)), take: 1, life: [2.2, 3], fall: 0.5, slow: 0.7, size: [0.045, 0.075], stretch: 0.1, dim: 0.2 },
  };
  const bag = ["peony", "ring", "palm", "willow"];
  for (let i = bag.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); const t = bag[i]; bag[i] = bag[j]; bag[j] = t; }
  const mainBreak = BREAKS[bag[0]];
  const doubleBreak = BREAKS[bag[1]];
  const kingBreak = BREAKS[bag[2]];

