  const comets = pop("comets", {
    spawn: { burst: { count: [Math.max(1, Math.round(3 * intensity)), Math.round(6 * intensity)], every: [1.6, 3.2] }, on: point() },
    lifetime: [1, 1.6],
    init: { v: up(1).mul(range(8, 11).mul(sv)).add(cone(26).mul(range(1.5, 3))), size: range(0.035 * scale, 0.06 * scale) },
    accel: gravity().mul(0.6).add(drag(0.3)),
    size: attr("size").mul(curve([0, 1], [1, 0.6])),
    color: curve([0, hdr(5, 3.6, 1.4)], [1, hdr(2.2, 1, 0.3)]),
    alpha: curve([0, 0], [0.07, 1], [0.8, 0.8], [1, 0]).mul(flicker(14, 0.45)),
    maxParticles: Math.ceil(14 * boost),
    render: sprite({ texture: "textures/ember", blend: "add", align: "velocity", stretch: 0.11 }),
  });
  const crackle = pop("crackle", {
    spawn: when(comets.dies),
    inherit: { p: comets.p },
    lifetime: [0.5, 1.1],
    init: { v: sphereDir().mul(range(0.9, 1.8)), size: range(0.02 * scale, 0.04 * scale) },
    accel: gravity().mul(0.25).add(drag(0.8)),
    size: attr("size").mul(curve([0, 1], [1, 0.3])),
    color: theme.spark.mul(curve([0, 1], [1, 0.35])),
    alpha: curve([0, 0], [0.1, 1], [1, 0]).mul(flicker(18, 0.5)),
    maxParticles: Math.ceil(10 * boost),
    render: sprite({ texture: "textures/mote", blend: "add" }),
  });

  // The big one: rarely \u2014 tens of seconds apart, on a seeded phase \u2014 a heavier stack climbs half
  // again as high, hangs, and breaks OVERSIZED in its own dealt geometry, igniting white-hot
  // before the duotone takes over. It out-reads everything else in the show, then crackle-twinkles
  // out like the regular blooms.
  const kingshell = pop("kingshell", {
    spawn: { burst: { count: [Math.round(56 * intensity), Math.round(72 * intensity)], every: [17, 34] }, on: point() },
    delay: 9 + rand() * 9,
    lifetime: [1.45, 1.6],
    init: { v: up(19 * sv).add(cone(2).mul(range(0.2, 0.8))), size: range(0.04 * scale, 0.06 * scale) },
    accel: gravity().mul(0.85).add(drag(0.35)),
    size: attr("size").mul(curve([0, 1], [1, 0.7])),
    color: curve([0, hdr(5, 3.4, 1.4)], [1, hdr(2.6, 1.3, 0.45)]),
    alpha: curve([0, 0], [0.05, 0.95], [0.85, 0.75], [1, 0]).mul(flicker(10, 0.3)),
    maxParticles: Math.ceil(76 * boost),
    render: sprite({ texture: "textures/ember", blend: "add", align: "velocity", stretch: 0.09 }),
  });
