    spawn: when(kingshell.dies),
    inherit: { p: kingshell.p },
    lifetime: [2.2, 3],
    init: { v: kingBreak.v().mul(1.6), size: range(0.09 * scale, 0.15 * scale) },
    accel: gravity().mul(kingBreak.fall).add(drag(kingBreak.slow)),
    size: attr("size").mul(curve([0, 1], [0.6, 0.85], [1, 0.35])),
    color: curve([0, hdr(5.5, 5.2, 4.6)], [0.35, theme.a], [0.75, theme.b], [1, theme.b.mul(0.25)]),
    alpha: curve([0, 0], [0.04, 1], [0.55, 0.9], [0.75, 0.25], [1, 0]).mul(flicker(8, 0.3)).add(curve([0, 0], [0.55, 0], [0.8, 0.85], [1, 0]).mul(flicker(12, 0.55))).clamp01(),
    maxParticles: Math.ceil(80 * boost),
